def try_identity_with_fix():
    output = [row[:] for row in grid]
    for r in range(30):
        if output[r][:3] == [8,8,8]:
            # Replace with symmetric counterpart
            sym_r = 29 - r
            if output[sym_r][:3] == [8,8,8]:
                # Both have 8 8 8, swap
                output[r], output[sym_r] = output[sym_r][:], output[r]
            else:
                output[r] = output[sym_r][:]
    return output

